import { HonoRequest } from "../clone/src/request.ts"
import { parseBody as headParseBody } from "../clone/src/utils/body.ts"
import { parseBody as baseParseBody } from "./base-body.ts"
import { Hono } from "../clone/src/hono.ts"

for (const [name, parseBody] of [['base', baseParseBody], ['head', headParseBody]] as const) {
  for (const kind of ['multipart', 'urlencoded'] as const) {
