    body.append('foo', 'bar')
    const req = new HonoRequest(new Request('http://localhost/', { method: 'POST', body }))
    const form = await req.formData()
    assert.equal(form.get('foo'), 'bar')
    try {
      const result = await parseBody(req)
      console.log(name, kind, JSON.stringify(result))
      if (name === 'base') assert.equal(result.foo, 'bar')
      if (name === 'head' && kind === 'urlencoded') assert.equal(result.foo, undefined)
    } catch (e) {
      if (name === 'base') throw e
      console.log(name, kind, String(e))
    }
  }
}

